CREATE TABLE IF NOT EXISTS rentals (id BIGINT AUTO_INCREMENT PRIMARY KEY, carId BIGINT NOT NULL, renterId BIGINT NOT NULL, startAt DATETIME(6) NOT NULL, endAt DATETIME(6) NOT NULL, status VARCHAR(50) NOT NULL, totalPrice DECIMAL(10, 2) NOT NULL, createdAt DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6) NOT NULL, cancelledAt DATETIME(6) NULL, CONSTRAINT fk_rentals_carId__id FOREIGN KEY (carId) REFERENCES cars(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_rentals_renterId__id FOREIGN KEY (renterId) REFERENCES users(id) ON DELETE CASCADE ON UPDATE RESTRICT);
